// 查表: 返回字形指针或 NULL
static inline const uint16_t* cjk_lookup(uint32_t cp) {
    int lo = 0, hi = CJK_FONT_N - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        if (cjk_codepoints[mid] == cp) return cjk_bitmaps[mid];
        if (cjk_codepoints[mid] < cp) lo = mid + 1; else hi = mid - 1;
    }
    return 0;
}
